00566             static vec<4, int, Q> call(vec<4, int, Q> const& a, vec<4, int, Q> const& b)
00567             {
00568                 vec<4, int, Q> Result;
00569                 Result.data = vmulq_s32(a.data, b.data);
00570                 return Result;
00571             }
00572         };
00573 
00574         template<qualifier Q>
00575         struct compute_vec4_div<float, Q, true>
00576         {
00577             static vec<4, float, Q> call(vec<4, float, Q> const& a, vec<4, float, Q> const& b)
00578             {
00579                 vec<4, float, Q> Result;
00580 #if GLM_ARCH & GLM_ARCH_ARMV8_BIT
00581                 Result.data = vdivq_f32(a.data, b.data);
00582 #else
00583                 /* Arm assembler reference:
00584                  *
00585                  * The Newton-Raphson iteration: x[n+1] = x[n] * (2 - d * x[n])
00586                  * converges to (1/d) if x0 is the result of VRECPE applied to d.
00587                  *
00588                  * Note: The precision usually improves with two interactions, but more than two iterations are not helpful. */
00589                 float32x4_t x = vrecpeq_f32(b.data);
00590                 x = vmulq_f32(vrecpsq_f32(b.data, x), x);
00591                 x = vmulq_f32(vrecpsq_f32(b.data, x), x);
00592                 Result.data = vmulq_f32(a.data, x);
00593 #endif
00594                 return Result;
00595             }
00596         };
00597 
00598         template<qualifier Q>
00599         struct compute_vec4_equal<float, Q, false, 32, true>
00600         {
00601             static bool call(vec<4, float, Q> const& v1, vec<4, float, Q> const& v2)
00602             {
00603                 uint32x4_t cmp = vceqq_f32(v1.data, v2.data);
00604 #if GLM_ARCH & GLM_ARCH_ARMV8_BIT
00605                 cmp = vpminq_u32(cmp, cmp);
00606                 cmp = vpminq_u32(cmp, cmp);
00607                 uint32_t r = cmp[0];
00608 #else
00609                 uint32x2_t cmpx2 = vpmin_u32(vget_low_u32(cmp), vget_high_u32(cmp));
00610                 cmpx2 = vpmin_u32(cmpx2, cmpx2);
00611                 uint32_t r = cmpx2[0];
00612 #endif
00613                 return r == ~0u;
00614             }
00615         };
00616 
