00655         template<qualifier Q>
00656         struct compute_vec4_nequal<float, Q, false, 32, true>
00657         {
00658             static bool call(vec<4, float, Q> const& v1, vec<4, float, Q> const& v2)
00659             {
00660                 return !compute_vec4_equal<float, Q, false, 32, true>::call(v1, v2);
